import math
import sys

class Point:
    def __init__(self, v, w, x, y, z):
        self.v = v
        self.w = w
        self.x = x
        self.y = y
        self.z = z

    def magnitude(self):
        return math.sqrt(self.v ** 2 + self.w ** 2 + self.x ** 2 + self.y ** 2 + self.z ** 2)

def check_angle(a, b):
    magA = a.magnitude()
    magB = b.magnitude()
    dot = a.v * b.v + a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z
    angle_deg = math.degrees(math.acos(dot / (magA * magB))) if magA != 0 and magB != 0 else 0
    return angle_deg < 90

def main():
    input_lines = sys.stdin.read().strip().split('\n')
    n = int(input_lines[0])
    if n > 11:
        print(0)
        return
    pts = []
    for i in range(1, n + 1):
        parts = list(map(int, input_lines[i].split()))
        a, b, c, d, e = parts
        pts.append(Point(a, b, c, d, e))
    valid_indices = set()
    for i in range(n):
        is_valid = True
        for j in range(n):
            for k in range(n):
                if i != j and i != k and j != k:
                    p1 = pts[j]
                    p2 = pts[k]
                    p3 = pts[i]
                    v1 = Point(p1.v - p3.v, p1.w - p3.w, p1.x - p3.x, p1.y - p3.y, p1.z - p3.z)
                    v2 = Point(p2.v - p3.v, p2.w - p3.w, p2.x - p3.x, p2.y - p3.y, p2.z - p3.z)
                    if check_angle(v1, v2):
                        is_valid = False
        if is_valid:
            valid_indices.add(i + 1)
    if not valid_indices:
        print(0)
    else:
        print(len(valid_indices))
        for idx in sorted(valid_indices):
            print(idx)

if __name__ == "__main__":
    main()

